	if (!lock) return 0;
	const entries = Object.entries(lock.skills).filter(([name]) => matchesSkillFilter(name, skillFilter));
	const installedAt = new Map((await listInstalledSkills({
		global: false,
		cwd
	})).map((skill) => [sanitizeName(skill.name), skill.canonicalPath]));
	const states = await Promise.all(entries.map(([name, entry]) => getLockedSkillState(name, entry, cwd, installedAt.get(sanitizeName(name)))));
	const modified = entries.filter((_, index) => states[index] === "modified");
