	const options = {
		help: values.help,
		fullDepth: values["full-depth"],
		skill: values.skill?.[0],
		agent: values.agent
	};
	if (values.skill && values.skill.length > 1) errors.push(diagnostics.SKILLS_DUPLICATE_OPTION({ option: "--skill" }));
	for (const option of unknown) errors.push(diagnostics.SKILLS_UNKNOWN_OPTION({ option }));
