		if (sourceArgs.length === 0) fail(diagnostics.SKILLS_MISSING_ARGUMENT({ name: "source" }), `\n${getUseHelp()}`);
		if (sourceArgs.length > 1) fail(diagnostics.SKILLS_MULTIPLE_SOURCES({ received: sourceArgs }));
