async function launchAgentInteractively(agent, prompt, spawnImpl = spawnAgent) {
	const config = USE_AGENT_CONFIGS[agent];
	if (!config) throw unsupportedAgent(agent);
	return new Promise((resolve, reject) => {
		const child = spawnImpl(config.command, [...config.args, prompt], { stdio: "inherit" });
		let settled = false;
		child.on("error", (error) => {
			if (settled) return;
			settled = true;
			if (error.code === "ENOENT") {
				reject(diagnostics.SKILLS_USE_AGENT_COMMAND_NOT_FOUND({
					agent: agents[agent].displayName,
					command: config.command
				}));
				return;
			}
			reject(error);
		});
		child.on("close", (code) => {
			if (settled) return;
			settled = true;
			resolve(code ?? 1);
		});
	});
}
